INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1209, 179, 1, '😊', '小鹿今天心情不太好，一个人坐在角落里。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1210, 179, 2, '🤗', '为什么会有这种感觉呢？小鹿想了想。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1211, 179, 3, '💝', '朋友走过来，轻轻抱了抱小鹿，说："我陪你。"');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1212, 179, 4, '🥰', '小鹿把心里的话说了出来，感觉好多了。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1213, 179, 5, '💕', '原来关心别人和被别人关心，都是那么温暖。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1214, 179, 6, '❤️', '小鹿不再难过了，试着对大家笑一笑。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1215, 179, 7, '🌈', '和朋友一起做了一件事，小鹿觉得很开心。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1216, 179, 8, '🥰', '小鹿做了一张小卡片送给喜欢的人。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1217, 179, 9, '🌸', '心情像天气一样会变化，小鹿学会了面对它。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1218, 179, 10, '💕', '小鹿明白了，每一种感受都值得被认真对待。');
