INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1479, 206, 1, '🛁', '早上好！小鳄鱼该起床啦，新的一天开始咯。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1480, 206, 2, '🛁', '先刷刷牙，上刷刷下刷刷，牙齿白白亮亮！');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1481, 206, 3, '🧴', '自己穿衣服，先穿小内裤，再套上T恤。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1482, 206, 4, '🧹', '吃饭啦！蔬菜肉肉米饭都要吃，不挑食才健康。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1483, 206, 5, '💧', '吃完饭要漱口，咕噜咕噜吐出来。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1484, 206, 6, '🧴', '饭前便后要洗手，搓搓手心搓搓手背。');
