INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1829, 241, 1, '🧚', '很久很久以前，在一个神秘山谷里，住着一只小蜗牛。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1830, 241, 2, '⚔️', '有一天，小蜗牛发现了一张神秘的地图，上面画着奇怪的路。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1831, 241, 3, '🗺️', '小蜗牛沿着地图走啊走，来到了一片从未见过的森林。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1832, 241, 4, '👑', '路上遇到了一个谜语，小蜗牛想了好久终于解开了！');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1833, 241, 5, '👑', '一条大河挡住了去路，小蜗牛想出了巧妙的办法过了河。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1834, 241, 6, '⚔️', '前方出现了一个难题，小蜗牛鼓起勇气去面对。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1835, 241, 7, '🐉', '就在最困难的时候，小蜗牛想出了一个好主意！');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1836, 241, 8, '⚔️', '小蜗牛帮助了路上遇到的新朋友，朋友也帮了小蜗牛。');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1837, 241, 9, '🗺️', '经过千辛万苦，小蜗牛终于到达了目的地！');
INSERT INTO book_page (id, book_id, page_num, illustration, text) VALUES (1838, 241, 10, '🧙', '小蜗牛明白了：勇敢和善良，是最了不起的魔法。');
